// План specs/admin-plans.md, 1.7 (кейс AP-05). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab } from './plans-helpers';
import { accountRows, loadedRowCount, filterControl, filterOptions, selectFilter, expectColumnEqualsOrEmpty, FILTER } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Source filter keeps only rows with the selected source, for every option #ca557707 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(180_000);
    await setLanguage(page, 'en');
    await openPlansTab(page);
    const total = await loadedRowCount(page);

    const control = filterControl(page, FILTER.sources);
    const options = await filterOptions(page, control, 'All sources');
    expect(options.length).toBeGreaterThan(0);
    // Список значений берём фактический (на 04.10: Free, Trial, Assigned, Stripe, Grandfathered).
    for (const option of options) {
      await test.step(option, async () => {
        await selectFilter(page, control, option);
        await expectColumnEqualsOrEmpty(page, 'Source', option);
      });
    }

    await selectFilter(page, control, 'All sources');
    await expect(accountRows(page)).toHaveCount(total);
  });
});
